vec3 c1 = u_col1;
vec3 c2 = u_col2;

// --- 2. EDGE FIX (the secret) ---
// We use the variable 'u_isFlat' created for this.
// The black cut happens ONLY in the 2D preview.
if (u_isFlat && (u < 0.0 || u > 1.0 || v < 0.0 || v > 1.0)) {
    return vec3(0.0); 
}

// --- 3. LOGICA GRADIENTE ---
float pos = v;

// clamp makes sure that on the 3D surface the colors extend
// up to the edges instead of doing strange things or inverting the gradient.
pos = clamp(pos, 0.0, 1.0);

// --- 4. OUTPUT ---
return mix(c1, c2, pos);

